import unittest

from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_lines


def make_shift(worker, day, start, end):
    return Shift(worker, day, Span(start * 60, end * 60))


class TimesheetLinesTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [
            make_shift("Ola", "mon", 9, 11),
            make_shift("Brisa", "mon", 9, 13),
            make_shift("Brisa", "tue", 9, 17),
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Brisa: 2 shifts, 12.0 hours",
                "Ola: 1 shifts, 2.0 hours",
            ],
        )

    def test_one_decimal_place(self):
        shift = Shift("Ola", "mon", Span(540, 615))
        self.assertEqual(
            timesheet_lines([shift]),
            ["Ola: 1 shifts, 1.2 hours"],
        )

    def test_ties_break_by_name(self):
        shifts = [
            make_shift("Zed", "mon", 9, 10),
            make_shift("Amy", "tue", 9, 10),
        ]
        lines = timesheet_lines(shifts)
        self.assertTrue(lines[0].startswith("Amy"))

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker(self):
        shifts = [
            make_shift("Ola", "mon", 9, 10),
            make_shift("  ", "mon", 10, 11),
        ]
        with self.assertRaises(ValueError):
            timesheet_lines(shifts)
